def backfill_wallets(apps, schema_editor):
    Payment = apps.get_model('catalog', 'Payment')
    WalletAccount = apps.get_model('catalog', 'WalletAccount')
    WalletLedgerEntry = apps.get_model('catalog', 'WalletLedgerEntry')
    accounts = {}
    for beneficiary in ('owner', 'developer'):
        accounts[beneficiary], _ = WalletAccount.objects.get_or_create(
            beneficiary=beneficiary, provider='relworx', currency='UGX'
        )
    for payment in Payment.objects.filter(status='paid').iterator():
        base = payment.amount
        fee = payment.provider_charge or Decimal('0')
        net = max(Decimal('0'), payment.amount - fee)
        commission = min(net, (base * Decimal('0.20')).quantize(Decimal('0.01')))
        owner_amount = max(Decimal('0'), net - commission)
        Payment.objects.filter(pk=payment.pk).update(
            base_amount=base, provider_fee_estimate=Decimal('0'),
            provider_net_amount=net, developer_commission=commission,
        )
        if owner_amount:
            WalletLedgerEntry.objects.get_or_create(
                idempotency_key=f'payment:{payment.pk}:owner',
                defaults={'wallet_account': accounts['owner'], 'payment': payment,
                          'entry_type': 'payment_credit', 'amount': owner_amount,
                          'metadata': {'payment_reference': payment.reference},
                          'created_at': payment.confirmed_at or payment.created_at},
            )
        if commission:
            WalletLedgerEntry.objects.get_or_create(
                idempotency_key=f'payment:{payment.pk}:developer',
                defaults={'wallet_account': accounts['developer'], 'payment': payment,
                          'entry_type': 'commission_credit', 'amount': commission,
                          'metadata': {'payment_reference': payment.reference},
                          'created_at': payment.confirmed_at or payment.created_at},
            )


